(()=>{'use strict';const $=id=>document.getElementById(id),KEY='staycontrol-mobile-token';let token='',items=[],filter='all',busy=false,first=true;
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
try{token=localStorage.getItem(KEY)||'';items=JSON.parse(localStorage.getItem('staycontrol-mobile-feed')||'[]');}catch{}
const hash=new URLSearchParams(location.hash.slice(1));if(hash.get('token')){$('pair-token').value=hash.get('token');history.replaceState(null,'',location.pathname);}
async function api(path,payload){const response=await fetch('./api/mobile/'+path,{method:payload?'POST':'GET',headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},...(payload?{body:JSON.stringify(payload)}:{}),cache:'no-store',signal:AbortSignal.timeout(10000)});const result=await response.json();if(!response.ok)throw Error(result.error||'Não foi possível acessar a central.');return result;}
function render(){const connected=!!token;$('setup').hidden=connected;$('dashboard').hidden=!connected;$('unread').textContent=items.filter(n=>!n.read).length;$('total').textContent=items.length;
const visible=items.filter(n=>filter==='all'||filter==='unread'&&!n.read||filter==='alert'&&n.severity==='alert');$('notices').innerHTML=visible.map(n=>`<article class="notice ${n.severity==='alert'?'alert':''} ${!n.read?'unread':''}"><div class="meta"><span>${n.severity==='alert'?'ALERTA':'ATIVIDADE'}${n.source==='simulation'?' · SIMULAÇÃO':''}</span><time>${esc(new Date(n.at).toLocaleString('pt-BR'))}</time></div><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p>${n.read?'<small>Lida</small>':`<button data-read="${esc(n.id)}">Marcar como lida</button>`}</article>`).join('')||'<p class="empty">Nenhuma notificação neste filtro.</p>';}
async function refresh(){if(!token||busy)return;busy=true;try{const feed=await api('feed');items=feed.items;try{localStorage.setItem('staycontrol-mobile-feed',JSON.stringify(items));}catch{}$('connection').textContent='Central conectada · monitoramento '+(feed.armed?'ativado':'desativado')+' · '+new Date().toLocaleTimeString('pt-BR');$('push-info').textContent=feed.push.ready?'Serviço push configurado. Toque em “Ativar notificações” para autorizar este celular.':'Histórico conectado. Notificações com o aplicativo fechado aguardam configuração de HTTPS e Web Push na central.';$('message').textContent='';first=false;render();}catch(error){$('connection').textContent='Sem atualização da central · mostrando o último histórico disponível.';$('message').textContent=error.message;}finally{busy=false;}}
$('pair-form').onsubmit=async event=>{event.preventDefault();const candidate=$('pair-token').value.trim();if(!/^[A-Za-z0-9_-]{40,60}$/.test(candidate)){$('message').textContent='Código de vinculação inválido.';return;}token=candidate;try{await api('feed');localStorage.setItem(KEY,token);items=[];render();await refresh();}catch(error){token='';$('message').textContent=error.message;render();}};
$('refresh').onclick=refresh;$('read-all').onclick=async()=>{try{await api('read',{id:'all'});await refresh();}catch(error){$('message').textContent=error.message;}};
document.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.filter){filter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b===button));render();}if(button.dataset.read){try{await api('read',{id:button.dataset.read});await refresh();}catch(error){$('message').textContent=error.message;}}});
$('disconnect').onclick=()=>{token='';items=[];try{localStorage.removeItem(KEY);localStorage.removeItem('staycontrol-mobile-feed');}catch{}$('connection').textContent='Celular desconectado. O administrador pode revogar o vínculo na central.';render();};
$('push').onclick=async()=>{const button=$('push');button.disabled=true;try{if(!isSecureContext||!('PushManager' in window)||!('Notification' in window))throw Error('Use HTTPS e um navegador compatível. No iPhone, abra o aplicativo instalado pela Tela de Início.');const feed=await api('feed');if(!feed.push.ready)throw Error('A central ainda precisa configurar o serviço Web Push. O histórico já funciona.');const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Notificações não foram permitidas.');const registration=await navigator.serviceWorker.ready;const raw=atob(feed.push.publicKey.replace(/-/g,'+').replace(/_/g,'/'));const key=Uint8Array.from(raw,c=>c.charCodeAt(0));const sub=await registration.pushManager.getSubscription()||await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});await api('subscribe',{subscription:sub.toJSON()});$('push-info').textContent='Notificações ativadas neste aparelho. Peça um teste à central.';}catch(error){$('message').textContent=error.message;}finally{button.disabled=false;}};
if('serviceWorker' in navigator&&isSecureContext)navigator.serviceWorker.register('./sw.js').catch(()=>{});render();refresh();setInterval(()=>{if(document.visibilityState==='visible')refresh();},10000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refresh();});})();
